'use strict';
const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const base='releases/v386',root='releases/v389',read=(p,n)=>fs.readFileSync(p+'/'+n,'utf8'),hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const manifest=JSON.parse(read(root,'manifest.json')),provenance=JSON.parse(read(root,'provenance.json'));
assert.equal(manifest.release,'v389');assert.equal(manifest.base_release,'v386');
for(const[name,expected]of Object.entries(manifest.files))assert.equal(hash(root+'/'+name),expected,name);
for(const[name,expected]of Object.entries(manifest.protected))assert.equal(hash(name),expected,name);
for(const[name,expected]of Object.entries(provenance.protected_base_files))assert.equal(hash(base+'/'+name),expected,name);
assert.deepEqual(fs.readdirSync(root).sort(),fs.readdirSync(base).sort());
assert.deepEqual(fs.readdirSync(root).filter(n=>hash(root+'/'+n)!==hash(base+'/'+n)).sort(),[...provenance.runtime_changes,'manifest.json','provenance.json'].sort());
assert.equal(read(root,'app.html'),read(base,'app.html').replaceAll('V386','V389').replace('v386-patrimony-evidence-20261031','v389-classification-search-20261031'));
const source='lts-category-registry.js',bundle='lts-v384-startup-1.js';
assert.equal(read(root,bundle),read(base,bundle).replace(read(base,source),read(root,source)));
for(const name of fs.readdirSync(root).filter(n=>n.endsWith('.js')&&![source,bundle].includes(n)))assert.equal(hash(root+'/'+name),hash(base+'/'+name),'exact calculation, label or transport '+name);
const registry=read(root,source),previous=read(base,source);
const loader=s=>s.slice(s.indexOf('  async function get('),s.indexOf('  function attach('));
assert.equal(loader(registry),loader(previous),'shared catalog loader and refresh contract exact');
assert.deepEqual([...registry.matchAll(/S\.rpc\('([^']+)'/g)].map(x=>x[1]),[...previous.matchAll(/S\.rpc\('([^']+)'/g)].map(x=>x[1]),'no new mutation or read capability');
const live=process.env.LTS_MOBILE_RELEASE||'v389';
assert.deepEqual(JSON.parse(read('mobile','current.json')),{release:live,entry:'../releases/'+live+'/app.html'});
assert.deepEqual(Object.keys(manifest.files).concat('manifest.json').sort(),fs.readdirSync(root).sort());
assert.equal(provenance.financial_source_data_changed,false);assert.equal(provenance.financial_reader_logic_changed,false);assert.equal(provenance.date_behavior_changed,false);
console.log(JSON.stringify({pass:true,release:'v389',complete_shared_catalog:true,stored_categories_exact:true,financial_and_date_code_exact:true,frozen_v386_exact:true}));
